import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),a={name:"guide/introduction.md"};function i(n,t,c,u,s,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p>Print Studio 用于制作可编辑的打印模板，注入业务数据后生成 HTML、PDF，或调用浏览器预览与打印。提供可视化设计器与纯代码 API 两条路径：既可以让用户在设计器里编辑模板，也可以完全通过代码创建模板并输出。</p><p>组件接入基于 Vue 3，其他浏览器环境通过命令式 API 挂载。</p><h2 id="三种使用形态" tabindex="-1">三种使用形态 <a class="header-anchor" href="#三种使用形态" aria-label="Permalink to &quot;三种使用形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>入口</th><th>适用场景</th></tr></thead><tbody><tr><td>可视化编辑</td><td><code>usePrintStudio()</code> + <code>&lt;PrintDesigner&gt;</code> 或 <code>createPrintStudio()</code> + <code>studio.mount({ el })</code></td><td>让用户在设计器里编辑模板</td></tr><tr><td>代码编辑 + 输出</td><td><code>createPrintStudio()</code>（不挂载视图）</td><td>业务代码创建 / 修改模板，直接输出</td></tr><tr><td>纯输出</td><td><code>createPrintRenderer()</code></td><td>已有模板 JSON，只注入数据输出</td></tr></tbody></table><p>三种形态共用同一条渲染管线；形态之间只是「谁来创建模板、要不要视图」的差别。</p><h2 id="创建方式" tabindex="-1">创建方式 <a class="header-anchor" href="#创建方式" aria-label="Permalink to &quot;创建方式&quot;">​</a></h2><p>前两种形态都需要先创建 DesignStudio 实例。按宿主环境选择创建方式：</p><table tabindex="0"><thead><tr><th>创建方式</th><th>来源</th><th>适用场景</th></tr></thead><tbody><tr><td><code>createPrintStudio(options?)</code></td><td><code>@printstack/print-studio</code></td><td>纯代码创建实例，拥有全部编辑与输出能力；需要界面时再调用 <code>studio.mount({ el })</code> 挂载</td></tr><tr><td><code>mountPrintDesigner(container, options?)</code></td><td><code>@printstack/print-studio/designer</code></td><td>非 Vue 宿主一次性挂载设计器：同步返回 <code>{ ready, studio, unmount }</code> 句柄，<code>ready</code> resolve 即界面与插件就绪；未传 <code>studio</code> 时自建实例，<code>unmount()</code> 时一并销毁</td></tr><tr><td><code>usePrintStudio()</code> + <code>&lt;PrintDesigner&gt;</code></td><td><code>@printstack/print-studio/vue</code></td><td>Vue 组件树集成：组合式函数创建实例并随 Vue 作用域销毁自动清理，组件负责渲染视图与生命周期</td></tr></tbody></table><p>三种方式得到同一套实例 API，差异只在生命周期归属：<code>createPrintStudio()</code> 由持有方自行 <code>dispose()</code>；<code>mountPrintDesigner()</code> 的生命周期跟随句柄；<code>usePrintStudio()</code> 跟随 Vue 作用域。详见 <a href="./../reference/vue-designer.html">Vue 集成</a>与 <a href="./../reference/studio.html">createPrintStudio()</a>。</p><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><p>从<a href="./getting-started.html">快速开始</a>跑通第一个设计器页面，再按<a href="./../tutorial/">循序渐进教程</a>系统学习；只想用代码完成「建模板 → 打印 → 导出」可走<a href="./../workflow/">完整工作流</a>。API 细节见 <a href="./../reference/studio.html">createPrintStudio() 参考</a>与<a href="./../reference/element-text.html">内置元素</a>；在线可运行示例见 <a href="../playground/index.html" target="_blank">Playground</a>。</p><h2 id="四个核心对象" tabindex="-1">四个核心对象 <a class="header-anchor" href="#四个核心对象" aria-label="Permalink to &quot;四个核心对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>说明</th><th>常见操作</th></tr></thead><tbody><tr><td><code>studio</code></td><td>DesignStudio 实例的业务操作入口</td><td><code>studio.document.loadJson(json)</code></td></tr><tr><td>打印文档 <code>PrintDocument</code></td><td>可保存为 JSON 的模板模型，含页面、元素与绑定配置</td><td><code>studio.document.data</code> 读取快照</td></tr><tr><td>打印数据 <code>input</code></td><td>本次输出的客户、订单、明细等数据</td><td><code>studio.preview({ customer: { name: &#39;张女士&#39; } })</code></td></tr><tr><td><code>PrintDesigner</code></td><td>连接实例的 Vue 可视化设计器组件</td><td><code>&lt;PrintDesigner :studio=&quot;studio&quot; /&gt;</code></td></tr></tbody></table><p>「打印模板」是整个可复用文档；「页面模板」是页面共用的页眉、页脚、背景（<code>studio.template</code> 管理）。打印数据不会写回模板；HTML / PDF 是输出结果，不能当作可编辑 JSON 加载。</p><h2 id="基本约定" tabindex="-1">基本约定 <a class="header-anchor" href="#基本约定" aria-label="Permalink to &quot;基本约定&quot;">​</a></h2><ul><li>位置、尺寸、边距单位 <strong>mm</strong>；字号 <strong>pt</strong>；旋转<strong>度</strong>；页面左上角为坐标原点，y 向下。</li><li><code>data</code> 是快照：修改快照不会编辑文档，更新必须走句柄或集合方法。</li><li>查询缺失对象返回 <code>undefined</code>；句柄在对象删除后其 <code>data</code> 也可能为 <code>undefined</code>；加载另一份文档后重新查询句柄。</li><li>模板渲染依赖浏览器环境，不支持 Node.js 服务端渲染（SSR）。</li></ul>',17)])])}const m=e(a,[["render",i]]);export{p as __pageData,m as default};
